# Builds the Tactical RMM Quick Support executable using the C# compiler that
# ships with Windows (.NET Framework 4.x) - no SDK or Visual Studio needed.
#
#   powershell -ExecutionPolicy Bypass -File build.ps1 [-Icon path\to\icon.ico]
#
# Default icon: branding\quicksupport.ico (generated by branding\make-icon.ps1).
#
# Output: dist\trmm-quicksupport.exe (server setup: see README.md)
#
# Note: the server appends its settings (api url + token) to the end of the
# file on download. Appending data invalidates an Authenticode signature, so a
# signed build will show as unsigned after download (SmartScreen may warn).
param(
    [string]$Icon = "",
    # development build: accepts --api= --token= --insecure on the command line
    # (never distribute it). Output: dist\trmm-quicksupport-dev.exe
    [switch]$Dev
)

$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
$csc = Join-Path $env:WINDIR "Microsoft.NET\Framework64\v4.0.30319\csc.exe"
if (-not (Test-Path $csc)) { $csc = Join-Path $env:WINDIR "Microsoft.NET\Framework\v4.0.30319\csc.exe" }
if (-not (Test-Path $csc)) { throw "csc.exe (.NET Framework 4.x) not found" }

$dist = Join-Path $root "dist"
New-Item -ItemType Directory -Force $dist | Out-Null
$out = Join-Path $dist ($(if ($Dev) { "trmm-quicksupport-dev.exe" } else { "trmm-quicksupport.exe" }))

$args = @(
    "/nologo",
    "/target:winexe",
    "/platform:anycpu",
    "/optimize+",
    "/out:$out",
    "/win32manifest:$(Join-Path $root 'src\app.manifest')",
    "/reference:System.dll",
    "/reference:System.Drawing.dll",
    "/reference:System.Windows.Forms.dll",
    "/reference:System.Web.Extensions.dll"
)
if ($Icon -eq "") { $Icon = Join-Path $root "branding\quicksupport.ico" }
if (-not (Test-Path $Icon)) { throw "icon not found: $Icon (run branding\make-icon.ps1)" }
$args += "/win32icon:$Icon"
if ($Dev) { $args += "/define:QS_DEV" }
$args += (Join-Path $root "src\QuickSupport.cs")

& $csc @args
if ($LASTEXITCODE -ne 0) { throw "build failed" }
Write-Host "Built $out"
